-- Dữ liệu mô phỏng sinh từ clean_seed.py. Các hash thử có mật khẩu ngẫu nhiên đã hủy.
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON;
SET ANSI_PADDING ON;
SET ANSI_WARNINGS ON;
SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON;
SET QUOTED_IDENTIFIER ON;
SET NUMERIC_ROUNDABORT OFF;
IF DB_NAME() <> N'IronPulse_SubmissionQA' OR NOT EXISTS (
    SELECT 1 FROM sys.extended_properties WHERE class = 0
      AND name = N'IronPulseAcademicPackage' AND CONVERT(nvarchar(30), value) = N'1.0.1'
)
    THROW 53101, N'Chọn database học thuật IronPulse_SubmissionQA đã được tạo bởi bước 01.', 1;
BEGIN TRANSACTION;

IF EXISTS (SELECT 1 FROM sys.extended_properties WHERE class=0 AND name=N'IronPulseSyntheticDataset') THROW 53106, N'Database học thuật đã có dataset.', 1;

IF EXISTS (SELECT 1 FROM dbo.[service_type]) THROW 53106, N'Bảng service_type có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[service_type] ON;
SET IDENTITY_INSERT dbo.[service_type] OFF;

IF EXISTS (SELECT 1 FROM dbo.[room]) THROW 53106, N'Bảng room có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[room] ON;
SET IDENTITY_INSERT dbo.[room] OFF;

IF EXISTS (SELECT 1 FROM dbo.[membership_plan]) THROW 53106, N'Bảng membership_plan có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[membership_plan] ON;
SET IDENTITY_INSERT dbo.[membership_plan] OFF;

IF EXISTS (SELECT 1 FROM dbo.[plan_inclusion]) THROW 53106, N'Bảng plan_inclusion có dữ liệu.', 1;

IF EXISTS (SELECT 1 FROM dbo.[equipment]) THROW 53106, N'Bảng equipment có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[equipment] ON;
SET IDENTITY_INSERT dbo.[equipment] OFF;

IF EXISTS (SELECT 1 FROM dbo.[person]) THROW 53106, N'Bảng person có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[person] ON;
SET IDENTITY_INSERT dbo.[person] OFF;

IF EXISTS (SELECT 1 FROM dbo.[staff]) THROW 53106, N'Bảng staff có dữ liệu.', 1;

IF EXISTS (SELECT 1 FROM dbo.[trainer]) THROW 53106, N'Bảng trainer có dữ liệu.', 1;

IF EXISTS (SELECT 1 FROM dbo.[trainer_certification]) THROW 53106, N'Bảng trainer_certification có dữ liệu.', 1;

IF EXISTS (SELECT 1 FROM dbo.[member]) THROW 53106, N'Bảng member có dữ liệu.', 1;

IF EXISTS (SELECT 1 FROM dbo.[membership]) THROW 53106, N'Bảng membership có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[membership] ON;
SET IDENTITY_INSERT dbo.[membership] OFF;

IF EXISTS (SELECT 1 FROM dbo.[payment]) THROW 53106, N'Bảng payment có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[payment] ON;
SET IDENTITY_INSERT dbo.[payment] OFF;

IF EXISTS (SELECT 1 FROM dbo.[session]) THROW 53106, N'Bảng session có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[session] ON;
SET IDENTITY_INSERT dbo.[session] OFF;

IF EXISTS (SELECT 1 FROM dbo.[pt_session]) THROW 53106, N'Bảng pt_session có dữ liệu.', 1;

IF EXISTS (SELECT 1 FROM dbo.[group_class_session]) THROW 53106, N'Bảng group_class_session có dữ liệu.', 1;

IF EXISTS (SELECT 1 FROM dbo.[booking]) THROW 53106, N'Bảng booking có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[booking] ON;
SET IDENTITY_INSERT dbo.[booking] OFF;

IF EXISTS (SELECT 1 FROM dbo.[member_service_usage]) THROW 53106, N'Bảng member_service_usage có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[member_service_usage] ON;
SET IDENTITY_INSERT dbo.[member_service_usage] OFF;

IF EXISTS (SELECT 1 FROM dbo.[equipment_maintenance_log]) THROW 53106, N'Bảng equipment_maintenance_log có dữ liệu.', 1;
SET IDENTITY_INSERT dbo.[equipment_maintenance_log] ON;
SET IDENTITY_INSERT dbo.[equipment_maintenance_log] OFF;

UPDATE dbo.service_type SET service_name=CASE service_type_id WHEN 1 THEN N'Tập gym tự do' ELSE N'Lớp nhóm phổ thông' END WHERE service_type_id IN (1,2);
EXEC sys.sp_addextendedproperty @name=N'IronPulseSyntheticDataset', @value=N'local05d-c.synthetic.v1';
EXEC sys.sp_addextendedproperty @name=N'IronPulseSyntheticReference', @value=N'2026-11-24T23:00:00';
COMMIT TRANSACTION;
